// Reference model: invert = 1-c (f32), luma = 0.2126*R+0.7152*G+0.0722*B, printed %g6
fn g6(v: f32) -> String {
    // emulate printf %g with precision 6 for a float promoted to double
    let d = v as f64;
    if d.is_nan() { return if v.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if d.is_infinite() { return if d < 0.0 { "-inf".into() } else { "inf".into() }; }
    let p = 6i32;
    let exp = if d == 0.0 { 0 } else { format!("{:e}", d).split('e').nth(1).unwrap().parse::<i32>().unwrap() };
    // recompute exponent the way printf does: from the %e rounded representation
    let e_str = format!("{:.*e}", (p-1) as usize, d);
    let x = e_str.split('e').nth(1).unwrap().parse::<i32>().unwrap();
    let _ = exp;
    if x < -4 || x >= p {
        let mant = e_str.split('e').next().unwrap();
        let mant = trim0(mant);
        format!("{}e{}{:02}", mant, if x < 0 {"-"} else {"+"}, x.abs())
    } else {
        let s = format!("{:.*}", (p - 1 - x).max(0) as usize, d);
        trim0(&s)
    }
}
fn trim0(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        let t = t.trim_end_matches('.');
        t.to_string()
    } else { s.to_string() }
}
fn main() {
    let a: Vec<String> = std::env::args().skip(1).collect();
    let mode = &a[0];
    let r: f32 = a[1].parse().unwrap();
    let g: f32 = a[2].parse().unwrap();
    let b: f32 = a[3].parse().unwrap();
    let luma: f32 = match mode.as_str() {
        "f32"    => 0.2126f32*r + 0.7152f32*g + 0.0722f32*b,
        "f64"    => (0.2126f64*(r as f64) + 0.7152f64*(g as f64) + 0.0722f64*(b as f64)) as f32,
        "f32fma" => (0.0722f32*b).mul_add(1.0, 0.2126f32*r + 0.7152f32*g),
        _ => panic!(),
    };
    println!("{} {} {} {} {} {}", g6(1.0f32-r), g6(1.0f32-g), g6(1.0f32-b), g6(luma), g6(luma), g6(luma));
}
